function makeR(){
  const esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  const rv=on=>'reveal'+(on?' in':'');
  const nav=t=>[['#sobre',t.navAbout],['#proyectos',t.navProjects],['#dotik','Dotik'],['#investigacion',t.navResearch],['#contacto',t.navContact]];
  const navM=t=>[['#sobre',t.navAbout],['#proyectos',t.navProjects],['#dotik','Dotik'],['#ajedrez',t.navChess],['#investigacion',t.navResearch],['#hitos',t.navMilestones],['#contacto',t.navContact]];
  return {
    esc,
    navLinks:t=>nav(t).map(([h,l])=>`<a href="${h}">${esc(l)}</a>`).join(''),
    mobileLinks:t=>navM(t).map(([h,l],i)=>`<a href="${h}" style="animation-delay:${i*50+60}ms"><span>0${i+1}</span>${esc(l)}</a>`).join(''),
    ticker:()=>[...TICKER,...TICKER].map(m=>`<div class="tick"><span>${esc(m)}</span><i></i></div>`).join(''),
    logos:list=>[...list,...list].map(l=>`<div class="logo-chip"><img src="${l.src}" alt="" width="30" height="30"><span>${esc(l.name)}</span></div>`).join(''),
    strengths:(t,on)=>t.strengths.map(s=>`<article class="strength ${rv(on)}"><div class="strength-top"><span>${s.n}</span><i></i></div><h3>${esc(s.title)}</h3><p>${esc(s.desc)}</p></article>`).join(''),
    philo:(t,on)=>t.philo.map(p=>`<article class="philo ${rv(on)}"><div class="philo-top"><span>${p.n}</span><span>${p.tag}</span></div><h3>${esc(p.title)}</h3><p>${esc(p.desc)}</p><p class="philo-rule">${esc(p.rule)}</p></article>`).join(''),
    method:(t,on)=>t.method.map(m=>`<article class="method ${rv(on)}"><div class="method-top"><span class="method-piece">${m.piece}</span><span>${m.n}</span></div><h3>${esc(m.title)}</h3><p>${esc(m.desc)}</p></article>`).join(''),
    stackTabs:(t,a)=>t.stack.map((g,i)=>`<button type="button" class="stack-tab${i===a?' active':''}" data-tab="${i}" role="tab" aria-selected="${i===a}"><span class="mono">0${i+1}</span><span class="stack-tab-name">${esc(g.group)}</span><span class="mono">${STACK_TOOLS[i].length+g.items.length}</span></button>`).join(''),
    stackPanel:(t,a)=>{const g=t.stack[a],names=STACK_TOOLS[a].map(x=>x.name.toLowerCase());
      return `<div class="stack-panel-head"><h3>${esc(g.group)}</h3><span>${g.n}</span></div><div class="tools">${STACK_TOOLS[a].map((x,j)=>`<div class="tool" style="animation-delay:${j*50}ms"><img src="${x.src}" alt="${esc(x.name)}" width="44" height="44"><span>${esc(x.name)}</span></div>`).join('')}</div><div class="concepts"><div class="concepts-label">${esc(t.conceptsLabel)}</div><div class="concepts-list">${g.items.filter(it=>!names.includes(it.toLowerCase())).map(it=>`<span>${esc(it)}</span>`).join('')}</div></div>`;},
    projects:(t,on)=>t.projects.map(p=>`<article class="project ${rv(on)}"><div class="browser-bar"><i></i><i></i><i></i><span>${esc(p.url)}</span></div><div class="project-img"><img src="${p.img}" alt="${esc(p.title)}" loading="lazy" width="1200" height="630"></div><div class="project-body"><div class="project-title"><h3>${esc(p.title)}</h3><span>${p.n}</span></div><p>${esc(p.desc)}</p><div class="tags">${p.tags.map(x=>`<span>${esc(x)}</span>`).join('')}</div>${p.href?`<a class="project-link" href="${p.href}" target="_blank" rel="noopener">${esc(t.visit)} <span>↗</span></a>`:''}</div></article>`).join(''),
    dotik:t=>t.dotik.map(d=>`<a class="dotik-card" href="${d.href}" target="_blank" rel="noopener"><div class="dotik-card-top"><span>${esc(d.url)}</span><span>↗</span></div><h3>${esc(d.title)}</h3><p>${esc(d.desc)}</p></a>`).join(''),
    research:(t,on)=>t.research.map(r=>`<article class="research ${rv(on)}"><div class="research-top"><span>${r.n}</span><i></i></div><h3>${esc(r.title)}</h3><p>${esc(r.desc)}</p></article>`).join(''),
    timeline:(t,on)=>t.timeline.map(e=>`<div class="tl-row ${rv(on)}"><div class="tl-when"><i></i>${esc(e.when)}</div><div><h3>${esc(e.title)}</h3><p>${esc(e.desc)}</p></div></div>`).join(''),
    moves:(t,played)=>t.san.map((s,i)=>`<span class="${i===played-1?'cur':i<played?'done':''}">${i%2===0?(i/2+1)+'. ':''}${esc(s)}</span>`).join('')
  };
}
